const queryUrl = (spec, scope) => {
  const encoded = btoa(JSON.stringify(spec)); // Query specs contain only ASCII codes/keys.
  return "https://cinecastiga.ro/intreaba?spec=" + encodeURIComponent(encoded)
    + (scope ? "&drill=1&evidence=" + encodeURIComponent(JSON.stringify(scope)) : "");
};
function hydrate(node) {
  node.value = Number(node.valueExact);
  node.hasChildren = Boolean(node.children?.length);
  node.isLeaf = !node.hasChildren;
  if (!node.isOther) {
    node.sourceSpec = { ...RAW_DATA.sourceSpec, filters: { ...RAW_DATA.sourceSpec.filters, cpvTerm: node.code } };
    node.evidenceScope = { cpvPrefixes: [node.code] };
    node.evidenceUrl = queryUrl(node.sourceSpec, node.evidenceScope);
    node.liveUrl = node.code.length === 2 ? queryUrl(node.sourceSpec) : node.evidenceUrl;
  }
  node.children?.forEach(hydrate);
  return node;
}
